package cliconfig

import (
	"errors"
	"fmt"
	"os"

	"go.yaml.in/yaml/v4"
)

func Load(path string) (Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read CLI configuration: %w", err)
	}

	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}, fmt.Errorf("decode CLI configuration: %w", err)
	}

	// basic checks...
	// no need for advanced validation because, at least for now, the config is autogenerated on the server
	if cfg.ServerURL == "" {
		return Config{}, errors.New("CLI configuration: server URL is required")
	}
	if cfg.CACert == "" {
		return Config{}, errors.New("CLI configuration: CA certificate is required")
	}
	if cfg.ClientCert == "" {
		return Config{}, errors.New("CLI configuration: client certificate is required")
	}
	if cfg.ClientKey == "" {
		return Config{}, errors.New("CLI configuration: client private key is required")
	}

	return cfg, nil
}
